INSERT INTO landslide_events (id, date, latitude, longitude, geometry, trigger, category, fatalities, description, source) VALUES
  ('glc-1061', '2009-07-01', 27.478, 88.527, ST_SetSRID(ST_MakePoint(88.527, 27.478), 4326), 'downpour', 'landslide', 0, 'Landslides triggered by heavy rains hit an iron bridge on the North Sikkim Highway over Bar Khola at 4th Mile at around 5:40 am.', 'NASA GLC bulk import'),
  ('glc-9853', '2016-08-16', 27.593, 88.492, ST_SetSRID(ST_MakePoint(88.492, 27.593), 4326), 'rain', 'landslide', 0, 'A major valley-blocking landslide at Dzongu in Sikkim, northern India. The landslide, which is large, has blocked the Kanaka River completely, and a lake has started to build behind it.', 'NASA GLC bulk import'),
  ('glc-4569', '2012-09-19', 27.8385, 88.556, ST_SetSRID(ST_MakePoint(88.556, 27.8385), 4326), 'downpour', 'landslide', 20, 'At least twenty one bodies, including those of the Indo-Tibetan Border Police (ITBP) and the Border Roads Organisation (BRO) personnel, have so far been found while eight persons are still missing due to flash flood and landslides in remote areas of North Sikkim, official sources said  The dead include four from the ITBP, two of their family members, and 12 junior officers from the BRO. Other victims were casual labourers, officials said.Most of the casualties are reported from Rangma range.Landslides were caused by heavy rains since September 19, Deputy Commissioner North district T W Khangsherpa said.There were about nine landslides blocking the main road between Chungthang and Mangan in the district, he said.', 'NASA GLC bulk import'),
  ('glc-4571', '2012-09-19', 27.6558, 88.605, ST_SetSRID(ST_MakePoint(88.605, 27.6558), 4326), 'downpour', 'landslide', 0, 'At least twenty one bodies, including those of the Indo-Tibetan Border Police (ITBP) and the Border Roads Organisation (BRO) personnel, have so far been found while eight persons are still missing due to flash flood and landslides in remote areas of North Sikkim, official sources said  The dead include four from the ITBP, two of their family members, and 12 junior officers from the BRO. Other victims were casual labourers, officials said.Most of the casualties are reported from Rangma range.Landslides were caused by heavy rains since September 19, Deputy Commissioner North district T W Khangsherpa said.There were about nine landslides blocking the main road between Chungthang and Mangan in the district, he said. Several landslides blocked the main roads between Chungthang and Pegong. Houses along Lachen river between Rangma and Chungthang were washed away in flash floods along Lachen river.', 'NASA GLC bulk import'),
  ('glc-9994', '2017-07-06', 27.02149311, 88.25902123, ST_SetSRID(ST_MakePoint(88.25902123, 27.02149311), 4326), 'continuous_rain', 'landslide', 0, 'Landslide causes water pipe to break, boulders obstruct road. Article: "North Bengal, along with the hills, has been experiencing constant, heavy showers ever since monsoon made its way to the region. The water levels of the rivers have been rising and the hills are being bothered by regular landslides."', 'NASA GLC bulk import'),
  ('glc-9785', '2017-05-26', 27.54295099, 88.59676956, ST_SetSRID(ST_MakePoint(88.59676956, 27.54295099), 4326), 'rain', 'landslide', 0, 'Large rockslide blocks rural road', 'NASA GLC bulk import'),
  ('glc-3986', '2011-09-25', 27.0605, 88.255, ST_SetSRID(ST_MakePoint(88.255, 27.0605), 4326), 'downpour', 'landslide', 0, 'Just when the life of people in the Hills was are limping back to normalcy after the 6.8 magnitude earthquake shook the entire eastern India, a massive landslide devoured a 30-metre stretch of Lebong Cart Road late Sunday night, cutting off connectivity with the northern parts of Darjeeling. However, no casualties have been reported in the incident.Lebong Cart Road connects the town with places like Singamari and tea gardens of Phoobsering, Banesbuck, Singla, Ging and also the army cantonment at Lebong. All vehicular movement has now been diverted from the Birch Hill Road.', 'NASA GLC bulk import'),
  ('glc-7031', '2015-05-24', 27.6163, 88.6586, ST_SetSRID(ST_MakePoint(88.6586, 27.6163), 4326), 'unknown', 'landslide', 0, 'Approximately 1200 tourists were stranded. The landslide blocked three switchbacks on the main road. By the evening, that stretch was impassable.', 'NASA GLC bulk import'),
  ('glc-57', '2007-04-11', 27.4459, 88.6193, ST_SetSRID(ST_MakePoint(88.6193, 27.4459), 4326), 'downpour', 'landslide', 0, '1000 tourists stranded, more than 180 vehicles stranded, 150 m stretch of road was covered, occurred at 2:00 local time', 'NASA GLC bulk import'),
  ('glc-1112', '2009-08-20', 27.1761, 88.5287, ST_SetSRID(ST_MakePoint(88.5287, 27.1761), 4326), 'downpour', 'mudslide', 0, 'Vehicles ply on 27 Mile, a landslide-affected stretch of NH31A, after fresh mudslide on Monday. The rain-triggered landslides and cave-ins have reduced the highway to a potholed and slushy track at numerous places, leading to frequent traffic jams and increase in travel time from two hours to more than double for Siliguri-bound vehicles from here on National Highway 31-A, lifeline for Sikkim and Kalimpong At least 10 places along the Highway had been hit by landslides, triggered by torrential rains over the past week. All these stretches, except Mile 27 area near Rambi have been cleared by the Border Roads Organisation (BRO).', 'NASA GLC bulk import'),
  ('glc-78', '2007-05-23', 27.3383, 88.6069, ST_SetSRID(ST_MakePoint(88.6069, 27.3383), 4326), 'rain', 'landslide', 0, 'along highway', 'NASA GLC bulk import'),
  ('glc-3997', '2011-09-30', 27.5161, 88.5575, ST_SetSRID(ST_MakePoint(88.5575, 27.5161), 4326), 'unknown', 'landslide', 0, 'The slide which occurred at Thingchim around 18 kilometers from Mangan towards Gangtok has disrupted the Mangan-Gangtok traffic again. The slide occurred recently which had brought big boulders that cover the stretch of around 40 feet. The restoration of the traffic has not been ascertained yet. The vehicles plying to the North District headquarter has been enrooted from Singtam via Dikchu Road. The commuters plying to Namok, Sweyem, Mangshilla and of some areas have to transship from this point.', 'NASA GLC bulk import'),
  ('glc-7021', '2015-06-27', 27.0076, 88.251, ST_SetSRID(ST_MakePoint(88.251, 27.0076), 4326), 'downpour', 'landslide', 1, 'The body of Phupu Doma Bhutia (45) was recovered by her relatives in her shanty in Ghoom on Sunday morning. It is suspected that a loose boulder tumbled down on the hut where Phupu lived.', 'NASA GLC bulk import'),
  ('glc-1094', '2009-08-16', 27.15977181, 88.63411246, ST_SetSRID(ST_MakePoint(88.63411246, 27.15977181), 4326), 'downpour', 'landslide', 1, 'In Katare village, about 80km from Kalimpong, a landslide brought down the house of Nima Tshering Lepcha at 9.30 last night, burying alive three-year-old Samuel. Nima’s two other children had a narrow escape.', 'NASA GLC bulk import'),
  ('glc-3643', '2011-06-23', 27.2879, 88.2579, ST_SetSRID(ST_MakePoint(88.2579, 27.2879), 4326), 'downpour', 'landslide', 16, 'June 24 – Sixteen people perished in three separate landslides which hit villages surrounding the West Sikkim district headquarters at Gyalshing. All three landslides took place at around 11.30 pm last night. Fourteen people were buried alive when rolling debris from a hill piled on a house, where 25 people were residing, at Khorong village in Yangthang constituency, Superintendent of Police, West Sikkim, AK Singh said.  The second landslide also buried a house at Tikjek village, killing on the spot a man identified as Kumar Thakur who lived there along with his friend. His friend had a miraculous escape when large chunks of mud and stones brought the house down like a pack of cards.   The bodies of eight victims have been retrieved so far as search and rescue operations were carried out throughout the night, DIG Range told this correspondent. Senior officials from the district administration, DC West, Santa Pradhan, SDPO West, SP West and MLA of the area PL Subba visited the affected', 'NASA GLC bulk import'),
  ('glc-210', '2007-08-25', 27.0713, 88.4308, ST_SetSRID(ST_MakePoint(88.4308, 27.0713), 4326), 'rain', 'landslide', 0, 'major landslide along road, closed for over 1 week, lifeline to Sikkim', 'NASA GLC bulk import'),
  ('glc-2392', '2010-09-04', 27.3702, 88.7334, ST_SetSRID(ST_MakePoint(88.7334, 27.3702), 4326), 'downpour', 'landslide', 0, 'Gangtok, Sep.4 (ANI): Incessant rains in the last few weeks have caused extensive landslides in Sikkim, as on Saturday, vehicular traffic on the road connecting Gangtok with Nathu La located along the India-China border came to a standstill due to landslides. Named the Jawaharlal Nehru Marg, the road holds high strategic importance for the movement of troops and their supplies.  It is also viewed as important for cross border trade and tourists who enjoy the rare experience of visiting the Nathu La Pass.  The worst affected spot has been "the 17th mile" where the road has been washed away to the extent of around 350 metres.  Reportedly, a gradient has slid down by 50 to 60 metres and a portion of the army barracks was badly damaged by the landslide.', 'NASA GLC bulk import'),
  ('glc-1091', '2009-08-16', 27.02459801, 88.43849551, ST_SetSRID(ST_MakePoint(88.43849551, 27.02459801), 4326), 'downpour', 'landslide', 2, 'Landslide killed, occurred at various places, including in tea gardens, along the National Highway 65 connecting Kurseong with Siliguri and Darjeeling, as also in areas like Pankhabari and Rohini Sunday morning following heavy rains over the past two days, said Kurseong sub-divisional police officer Rakesh Singh.', 'NASA GLC bulk import'),
  ('glc-218', '2007-08-29', 27.0096, 88.2548, ST_SetSRID(ST_MakePoint(88.2548, 27.0096), 4326), 'rain', 'landslide', 0, 'blocked Hwy 55 and railway transportation', 'NASA GLC bulk import'),
  ('glc-1755', '2010-04-17', 27.3341, 88.6083, ST_SetSRID(ST_MakePoint(88.6083, 27.3341), 4326), 'downpour', 'landslide', 0, 'Much ahead of the Monsoon, Gangtok is already reeling under the ipact of incessant rains and resultant landslides.  The Gangtok traffic came to a stand still when a major landslide hit the road at Pani House this afternoon. The highway was blocked for several hours when a portion of the wall above Pani House came crashing down leaving hundreds of vehicle stranded off in the National Highway 31- A. It took almost an hour for Deorali OP Police and the local people to clear the debris for traffic.  However, no human causalities were reported except for the minor damage of a Mahindra Bolero which was parked below the landslide area. Besides, the rainwater entered into one of the hotels located at Pani House leaving the owner and the staff panic-stricken.', 'NASA GLC bulk import'),
  ('glc-1995', '2010-06-16', 27.0765, 88.4808, ST_SetSRID(ST_MakePoint(88.4808, 27.0765), 4326), 'rain', 'landslide', 3, 'Siliguri, (IANS) At least three people were killed Thursday when a landslide destroyed a house in West Bengal''s Darjeeling district, police said. The incident occurred on the Tripi road of Upper Gumfa area in Kalimpong. The dead were identified as Surekha Bhutia (48) and her two children, Debita Bhutia (21) and Sanjong Bhutia (18). Two others in the house were seriously injured, said police officer Puran Subba.', 'NASA GLC bulk import'),
  ('glc-2360', '2010-08-29', 27.7276, 88.0446, ST_SetSRID(ST_MakePoint(88.0446, 27.7276), 4326), 'downpour', 'landslide', 0, '2010-08-31 12:22 PM  TAPLEJUNG: Landslides triggered by heavy rainfall since the past few days in Lelep VDC of the district has put 45 houses at the risk of being buried.  The landslides that occurred at around 10:00 pm on Sunday night has affected the residents of Batase and Sisne villages of the VDC with around 45 houses at high risk of being swept away.  Maize, millet and cardamom crops near the village have also been destroyed in the landslide causing huge loss to the farmers, local resident Prakash Fungjela said.  Likewise, the landslide has also polluted water sources in the villages and thereby increases the risk of spread of diseases like diarrhoea.', 'NASA GLC bulk import'),
  ('glc-9220', '2016-07-26', 27.1027, 88.1218, ST_SetSRID(ST_MakePoint(88.1218, 27.1027), 4326), 'downpour', 'landslide', 0, 'Landslide in Finchaytaar, Lodhoma, Darjeeling. There was a landslide nearby recently that killed three. Locals think this is caused from the nearby hydro project that uses explosives. Those impacted by landslide were moved to community hall.', 'NASA GLC bulk import'),
  ('glc-256', '2007-09-10', 27.3425, 88.6236, ST_SetSRID(ST_MakePoint(88.6236, 27.3425), 4326), 'rain', 'landslide', 0, 'destroyed a house, killed 1 and injured 1', 'NASA GLC bulk import'),
  ('glc-4908', '2013-06-08', 27.3721, 88.708, ST_SetSRID(ST_MakePoint(88.708, 27.3721), 4326), 'downpour', 'landslide', 0, 'Hundreds of tourists were stranded near Gangtok, following a landslide. "We faced many problems there was nothing to protect us (from cold). The person, who slept in the vehicle in night, might fall sick. Military persons gave food to everybody to eat. Locals helped us," a tourist, Sanjay Suri, said. Nearly 100 vehicles were struck as slush and the debris blocked the road nearly 15 kilometres off Gangtok after heavy rain. Gangtok is located in the Himalayans at an altitude of nearly 5,600 feet. Military personnel and locals aided the visitors, who slept either in cars or a nearby temple. The Border Roads Organisation (BRO) has started the clearing operations to make the road commutable for the travelers to leave for their destination. (2nd link) Around 600 tourists returning to Gangtok from Chhangu Lake, Baba Mandir and Nathu-la were stranded at 5th Mile, 15km from Gangtok, following a landslide on Jawaharlal Nehru Marg on Saturday evening, official sources said. "Around 5pm, when t', 'NASA GLC bulk import'),
  ('glc-4552', '2012-09-14', 27.0377, 88.3603, ST_SetSRID(ST_MakePoint(88.3603, 27.0377), 4326), 'downpour', 'landslide', 0, 'Landslides triggered by heavy overnight rain in the hills caused extensive damage in six tea gardens but planters said the digging being done under the 100-day rural job scheme was making the soil come loose.While work had to be stopped for the day in Takdah and Lopchu gardens because of the slides, Bannockburn, Phoobshering, Ging and Pussimbing reported loss of many tea bushes.“Takdah received around 18 inches of rainfall in the last 24 hours. Around 160 labourer quarters have suffered damage. A 40ft road in Takdah has been washed away in four places and five culverts have been damaged in landslides. There is no approach road to the garden factory now,” said Sandeep Mukherjee, the principal advisor to the Darjeeling Tea Association.', 'NASA GLC bulk import'),
  ('glc-5533', '2013-09-16', 27.0599, 88.4674, ST_SetSRID(ST_MakePoint(88.4674, 27.0599), 4326), 'downpour', 'landslide', 1, 'A construction worker has been killed in a landslide at Kalimpong in the Darjeeling District of West Bengal State, India. Witnesses report the landslip was quite small, and buried two men, one of whom was able to dig himself out. However the second man was trapped beneath an iron mesh, used to contain building materials, causing delays in digging him out. The worker was taken to a local hospital but declared dead on arrival. He has been named as Ritesh Chettri, a 30 year old man from Bhalukhop. The incident happened on Monday 16 September 2013 following heavy rain in the area over the weekend', 'NASA GLC bulk import'),
  ('glc-260', '2007-09-11', 27.2084, 88.4909, ST_SetSRID(ST_MakePoint(88.4909, 27.2084), 4326), 'rain', 'debris_flow', 0, 'occurred in afternoon, slide was 40 m long, disrupted traffic', 'NASA GLC bulk import'),
  ('glc-3813', '2011-07-20', 27.1141, 88.4658, ST_SetSRID(ST_MakePoint(88.4658, 27.1141), 4326), 'rain', 'landslide', 0, 'Siliguri : The road link between Siliguri and Sikkim was snapped for about six hours Wednesday after heavy overnight rains triggered a landslide on National Highway 31A in West Bengal''s Darjeeling district, police said.  Hundreds of vehicles remained stalled for six hours following the landslide, which resulted in a 20-foot wide crater on the highway, considered the lifeline to Sikkim.  "Around 500 vehicles were stranded on both sides. However, a few vehicles took other longer routes," said a police officer.  The General Reserve Engineer Force personnel managed to repair the road after a six-hour effort.  "The road was opened at 1.40 p.m.," said the officer.  National Highway 31A runs along the banks of the Teesta river linking the Sikkim capital Gangtok with Sevoke, near Siliguri, on National Highway 31.', 'NASA GLC bulk import'),
  ('glc-2113', '2010-07-21', 27.3773, 88.559, ST_SetSRID(ST_MakePoint(88.559, 27.3773), 4326), 'downpour', 'landslide', 0, 'Five houses were destroyed by landslides triggered by incessant rain at Zang in East Sikkim early this morning. Nobody was hurt as families living in these houses could escape just before the slides struck.  The mud slides also blocked the Singtam-Mangan road, which is an alternative route to North Sikkim Highway. The rubbles were cleared by the Border Roads Organisation for light vehicles later in the afternoon', 'NASA GLC bulk import'),
  ('glc-4990', '2013-06-27', 27.3765, 88.7628, ST_SetSRID(ST_MakePoint(88.7628, 27.3765), 4326), 'downpour', 'landslide', 0, 'The Mountain Black Cat Division of the Indian Army has rescued 230 tourists last night when they were stranded near Changu Lake (13300 ft height) , 15 km away from Nathu La, on India-China border in eastern Sikkim. Heavy rain and landslides in this area has cut off traffic. The nearest regiment of army jawans noticed nearly 47 vehicles carrying tourists who were stranded at night.', 'NASA GLC bulk import'),
  ('glc-1111', '2009-08-20', 27.1344, 88.4575, ST_SetSRID(ST_MakePoint(88.4575, 27.1344), 4326), 'downpour', 'landslide', 0, 'Minor landslides have also occurred at Melli Chalisey where one kachha house belonging to Khem Bahadur Ghataney has been affected. According to the residents, the house belonging to Khem Bahadur, which has been tilting is likely to affect other nearby houses if the rain continues in the same pace and gravity. “There is a possibility that another house belonging to P Biswakarma located in the same area will be damaged in the same manner,” the locals said. The torrential rains have also affected several roads linking to villages. Some of the damaged roads were cleared within the stipulated time while some roads are under the process of clearance.', 'NASA GLC bulk import'),
  ('glc-1102', '2009-08-19', 27.2644, 88.1365, ST_SetSRID(ST_MakePoint(88.1365, 27.2644), 4326), 'downpour', 'landslide', 2, 'Two persons were killed and 10 others were injured following a series of landslides and flashfloods triggered by incessant rains in Sombaria and Daramdin in west Sikkim since last night. According to the SDO, Soreng, Mr Bhim Thatal, Puspa Mani Pradhan and Sameer Subba died on the spot when flashfloods washed at least 10 houses and claimed a dozen cattles at Sombaria at 8.30 p.m. last evening.', 'NASA GLC bulk import'),
  ('glc-1056', '2009-07-22', 27.04, 88.264, ST_SetSRID(ST_MakePoint(88.264, 27.04), 4326), 'downpour', 'landslide', 0, 'The disruption of popular toy train services in Darjeeling disappointed the tourists as the rail track was damaged by the landslides in the region. The track has been washed away at Gayabari, Kerseong and Darjeeling due to heavy incessant rainfall and landslides from the hills.', 'NASA GLC bulk import'),
  ('glc-4394', '2012-06-07', 27.1748, 88.6458, ST_SetSRID(ST_MakePoint(88.6458, 27.1748), 4326), 'rain', 'landslide', 7, 'Seven persons, three of them children, were killed when landslides struck a village in East Sikkim after a spate of rain lashed the area last night. Four members of a family were also among those wiped out in the early morning strikes.', 'NASA GLC bulk import'),
  ('glc-6146', '2014-07-15', 27.059, 88.4694, ST_SetSRID(ST_MakePoint(88.4694, 27.059), 4326), 'rain', 'landslide', 0, 'With a landslide badly disrupting traffic, National Highway 31-A connecting Gangtok with Siliguri in West Bengal and considered Sikkim''s "lifeline" will be closed for a day from Wednesday for repairs. With a major chunk of the highway caving in near Kalimpong in Darjeeling district and threatening to cut off Sikkim from the rest of the country, the administration has roped in the services of General Reserve Engineer Force (GREF). According to the district administration, the highway will be closed for 24 hours from 6 a.m. Wednesday to enable the GREF to construct a Bailey bridge on the landslide-affected area for the traffic to resume. Both the Sikkim and Darjeeling administration have warned tourists and drivers against using the highway to avert any tragedy.', 'NASA GLC bulk import'),
  ('glc-2296', '2010-08-20', 27.167, 88.3652, ST_SetSRID(ST_MakePoint(88.3652, 27.167), 4326), 'downpour', 'complex', 0, 'Posted by Barun Roy on August 21st, 2010  Namchi: The heavy down pour last two days resulted in much damages at two Gram Panchayat units Lingee-Sokpay and Payoung-Kaw under Yangyany Block Administrative Centre. Kubernath Timshina, Panchayat President of Payoung-Kaw GPU, informs that in the wake of a huge landslide the family members and live stock of Ambika Prashad Adhakari of Millde Payoung have been shifted to other safe place since his house was heavily damaged by the slide.  The houses of Hemlal Adhakari and Rabilal Adhakari of Middle Payoung are also on the verge of collapse due to a heavy mud slip from the new cutting of PWD road. At Lingee village, following heavy rainfall the kitchen of Bhakti Maya Dabhari was completely buried by landslide and her house was also partly damaged. In Dara Karhaha ward of Payoung-Kaw Gram Panchayat Unit, the house of Tek Bdr. Rai was heavily damaged by the new cutting of PMGSY road and if the rain continues for one more day he has to be shifted to', 'NASA GLC bulk import'),
  ('glc-1125', '2009-08-26', 27.3746, 88.7648, ST_SetSRID(ST_MakePoint(88.7648, 27.3746), 4326), 'rain', 'landslide', 0, 'A major landslide at 17th Mile towards Tsomgo Lake has become a major factor of disappointment for the tourists visiting Sikkim. Almost all the tourists visiting Sikkim have expressed dissatisfaction for losing their chance to visit the famous high altitude lake. The State Police Department, Check Post has stopped issuing permits to tourists visiting Tsomgo Lake, Baba Mandir and Nathu-La border following massive landslides, which occurred near Kyongsala on July 26.', 'NASA GLC bulk import'),
  ('glc-2112', '2010-07-21', 27.5509, 88.6475, ST_SetSRID(ST_MakePoint(88.6475, 27.5509), 4326), 'downpour', 'landslide', 0, 'Gangtok, July 21: Five houses were destroyed by landslides triggered by incessant rain at Zang in East Sikkim early this morning. Nobody was hurt as families living in these houses could escape just before the slides struck.', 'NASA GLC bulk import'),
  ('glc-241', '2007-09-07', 27.201, 88.4883, ST_SetSRID(ST_MakePoint(88.4883, 27.201), 4326), 'rain', 'landslide', 0, 'over 18 places along road disrupted traffic and blocked areas', 'NASA GLC bulk import'),
  ('glc-5476', '2013-09-07', 27.3736, 88.7323, ST_SetSRID(ST_MakePoint(88.7323, 27.3736), 4326), 'rain', 'landslide', 0, 'The Army launched massive rescue operations in east and north Sikkim since Saturday and rescued 40 stranded tourists and several injured workers of an engineering firm caught in landslides. While the tourists were on their way to Nathu La, the engineering firm was based in Chungthang. "Around 3pm on Saturday, a massive landslide occurred at 14 Milestone of J N Marg near Kyangnosola (East Sikkim). A convoy of 11 vehicles ferrying 40 tourists to Nathu La were stranded in rain and bad weather. The group comprised five small children and 11 women. On receiving an alert, the Army swung into action and escorted the tourists to safety at the nearest camp. There, they were made comfortable. Milk was arranged for the children. They were also provided with bedding, blankets and medical aid to tide over the harsh weather during the night," said Gr Capt T K Singha, CPRO, Ministry of Defence, Kolkata. The following day, the landslides were cleared by the Border Roads personnel and the tourists we', 'NASA GLC bulk import'),
  ('glc-1032', '2009-05-26', 27.0095, 88.2592, ST_SetSRID(ST_MakePoint(88.2592, 27.0095), 4326), 'tropical_cyclone', 'landslide', 6, 'With the recovery of three more bodies, the toll in the landslides in West Bengal''s hill district of Darjeeling due to Cyclone Aila has risen to 27, police said today.   "We have recovered three bodies from the debris at Rangiabong under Jorbungalow police station area this (Thursday) morning. One of the bodies has been identified as Pramila Rai, 68," a senior official of the Jorbungalow police station said.   He said the teams of Natural Disaster Management Authority have started rescue operations in the cyclone-hit areas.   Meanwhile, state Home Secretary Ardhendu Sen reached Darjeeling Thursday morning to hold meetings with the district administration. He is likely to visit the landslide-affected zones and will also survey the situation there.   "Search operations are on in some areas as at least four people are still missing from the Darjeeling district after the cyclonic storm," the police officer said.   According to district administration sources, 14 bodies were found in ar', 'NASA GLC bulk import'),
  ('glc-1107', '2009-08-20', 27.0736, 88.4779, ST_SetSRID(ST_MakePoint(88.4779, 27.0736), 4326), 'continuous_rain', 'landslide', 1, 'Four-years-old Ashish Rai of Geetkolbong in Kalimpong sub-division was also killed by the landslide in that area.', 'NASA GLC bulk import'),
  ('glc-2201', '2010-08-05', 27.0366, 88.263, ST_SetSRID(ST_MakePoint(88.263, 27.0366), 4326), 'downpour', 'landslide', 0, 'Landslide in West Bengal''s Darjeeling district caused the roads to cave in, which in turn severely damaged the narrow gauge track on which the famous Toy train runs. Massive landslide occurred due to heavy downpour on Thursday. The landslide has upset all road links from Siliguri to various other places in Darjeeling district such as the hill resort of Darjeeling, Kalimpong, Kurseong and Sukna.', 'NASA GLC bulk import'),
  ('glc-6965', '2015-06-17', 27.0257, 88.4301, ST_SetSRID(ST_MakePoint(88.4301, 27.0257), 4326), 'downpour', 'landslide', 0, 'Note: one article listed multiple landslides, unspecific. Following heavy rainfall in the Darjeeling hills, there were three landslides at three spots on National Highway 31A, considered the lifeline of Sikkim.', 'NASA GLC bulk import'),
  ('glc-4393', '2012-06-07', 27.7565, 88.632, ST_SetSRID(ST_MakePoint(88.632, 27.7565), 4326), 'downpour', 'landslide', 7, 'As many as seven Nepali-speaking people have been killed in the landslide induced by downpour at Nathang Maong region in Sikkim on Thursday night. The deceased have been identified as Tika Rai, Dil Man Rai, Madi Maya Rai, Mahendra Rai, Neha Rai, Chandra Kumar Rai, and Mohan Rai, Indian media reported.', 'NASA GLC bulk import'),
  ('glc-126', '2007-07-16', 27.1499, 88.38, ST_SetSRID(ST_MakePoint(88.38, 27.1499), 4326), 'rain', 'mudslide', 0, 'closest to predicted location of Gauhati (336.70 km)', 'NASA GLC bulk import'),
  ('glc-1168', '2009-09-17', 27.1954, 88.6115, ST_SetSRID(ST_MakePoint(88.6115, 27.1954), 4326), 'rain', 'landslide', 0, 'A massive landslide that occurred in the morning of September 17 at 4th Mile has completely disrupted the traffic movement between Rongli, Rhenock and Rangpo in East Sikkim. The entire stretch has been washed away by the landslide creating trouble for the commuters.', 'NASA GLC bulk import'),
  ('glc-2214', '2010-08-06', 27.0375, 88.2627, ST_SetSRID(ST_MakePoint(88.2627, 27.0375), 4326), 'downpour', 'landslide', 0, 'The traffic along the National Highway 55 was disrupted on Friday following a heavy rainfall that triggered landslide in the Darjeeling Hills valley region. The landslide blocked all road links from Siliguri in the foothills to various other places in Darjeeling District. No human casualties, were, however, reported from Gayabari village, where the landslide caused extensive damage. “The trends of landslide are very dangerous here. We have 15 households here and all of them have been shifted to the Jawahar Jyoti Primary School nearby due to fear of further landslides,” said Dhan Bahadur Pradhan, a local resident of Gayabari.', 'NASA GLC bulk import'),
  ('glc-3943', '2011-08-23', 27.13862165, 88.22551799, ST_SetSRID(ST_MakePoint(88.22551799, 27.13862165), 4326), 'downpour', 'landslide', 5, 'Five persons including two minors were killed in two separate landslides incident in West Sikkim district, official sources said today. A cloud burst triggered a massive landslide at Samathang village, near Malbasey in West Sikkim in which three members of a family including two children were killed midnight last night, the sources said. Nirmaya Chettri (36) and her two daughters - Manju (16) and Anju (6) were killed while her husband Pratab Chettri was injured when the landslide destroyed their house, they said. In the second landslide incident two persons - Santa Bir Majhi and Sarki Maji working as casual labourers at a private construction site at Hee-Khola in West district were killed on the spot when loose muck from the construction site buried them in the site today, the sources said.', 'NASA GLC bulk import'),
  ('glc-5429', '2013-09-01', 27.3425, 88.2426, ST_SetSRID(ST_MakePoint(88.2426, 27.3425), 4326), 'downpour', 'landslide', 5, 'A family of five were all killed by a landslide that struck their home in Tamabong village in Sikkim State, northeast India, on the evening of Sunday 1 September 2013. The incident reportedly happened following heavy rains; landslides are a common problem after severe weather events, as excess pore water pressure can overcome cohesion in soil and sediments, allowing them to flow like liquids', 'NASA GLC bulk import'),
  ('glc-9074', '2016-07-20', 27.1176, 88.1069, ST_SetSRID(ST_MakePoint(88.1069, 27.1176), 4326), 'downpour', 'landslide', 3, 'At least three people died in a landslide in Rimbik area of Darjeeling on Wednesday. The state has been receiving heavy rains, triggering flash floods and landslides in several areas. The meteorological department has predicted more rainfall in the next 24 hours.', 'NASA GLC bulk import'),
  ('glc-4556', '2012-09-16', 27.1675, 88.3651, ST_SetSRID(ST_MakePoint(88.3651, 27.1675), 4326), 'downpour', 'landslide', 0, 'Landslides caused by heavy rainfall has blocked several roads in the South district of Sikkim, official sources said today. The road from Namchi to Phongla, Namchi to Melli and Namchi to Sumbuk were blocked due to landslides, as were the roads from Phongla to Bermiok and Phongla to Mamring.he road from Melli to Phongla and Melli to Sadam is also blocked while last night''s downpour also affected road connectivity from Yangang to Ravangla, Yangang to Singtam and Yangang to Lingmoo.', 'NASA GLC bulk import'),
  ('glc-3632', '2011-06-20', 27.0638, 88.4659, ST_SetSRID(ST_MakePoint(88.4659, 27.0638), 4326), 'rain', 'landslide', 0, 'In Kalimpong town, power was disrupted from around 10.30am this morning. Despite the rains no major landslides were reported from across the hills. “There have been a number of small landslips in various places but no casualties have been reported till now,” said a district official. A landslide at Birik on NH31A around 8.30pm today cut off Sikkim’s only road link once more. The road had shut down on Friday night after boulders came tumbling down at the same spot, 40km from Rangpo in Kalimpong subdivision. It had reopened around noon yesterday.', 'NASA GLC bulk import'),
  ('glc-9215', '2016-01-14', 27.1758, 88.5294, ST_SetSRID(ST_MakePoint(88.5294, 27.1758), 4326), 'unknown', 'rock_fall', 1, 'An unspecified number of people are feared trapped after a large piece of rock, estimated to measure about 150 metres, broke off a hillock and crashed down on a stretch of the national highway connecting Sikkim with Bengal. One body was recovered and three injured persons were rescued had been rescued till 8.30 am, officials said. “Three persons have been rescued including two boys. A body of a truck driver has been recovered. It is suspected that two more may be trapped in the debris. Rescue teams are working,” said the Amit P Javalgig, the district police superintendent. The incident happened between 5 am and 5:30 am on Thursday. It was not possible to ascertain immediately how many vehicles or people might be buried under the landslide which took place at Bhotebhir on NH10, about 1 km from Rangpo which marks the Bengal-Sikkim border. It is 75 km from Siliguri in West Bengal. NH10 is the only major road that connects Sikkim with the rest of the country and all movement of tourists, m', 'NASA GLC bulk import'),
  ('glc-9620', '2016-10-15', 27.172, 88.5292, ST_SetSRID(ST_MakePoint(88.5292, 27.172), 4326), 'downpour', 'landslide', 0, 'The road on way to Peiling in Sikkim remained cut off due to landslides at Namchi and Rangpo but the Lava-Lolegaon route in Darjeeling was still working, though only for cars and the small vehicles took long detour through the second route, the officials said.', 'NASA GLC bulk import'),
  ('glc-755', '2008-08-28', 27.337, 88.609, ST_SetSRID(ST_MakePoint(88.609, 27.337), 4326), 'downpour', 'landslide', 0, 'most affected villages of block level are Pabing, Changram, Doksing and Thami Dara', 'NASA GLC bulk import'),
  ('glc-1756', '2010-04-17', 27.322, 88.6087, ST_SetSRID(ST_MakePoint(88.6087, 27.322), 4326), 'downpour', 'landslide', 0, 'On the same day, another minor landslide was reported at Nam-Nang.', 'NASA GLC bulk import'),
  ('glc-4385', '2012-06-03', 27.7167, 88.5577, ST_SetSRID(ST_MakePoint(88.5577, 27.7167), 4326), 'downpour', 'landslide', 0, 'Around 65 vehicles carrying 400 tourists were left stranded at Lachen-Lachung last night, after heavy landslides triggered by torrential rain hit the picturesque North Sikkim. Sources in the tourism department said some of the cars started from Lachung at 3pm today after the Border Roads Organisation cleared the debris of the landslide at Theeng Bhir on way to Chungthang.', 'NASA GLC bulk import'),
  ('glc-7034', '2015-06-30', 27.0875, 88.6556, ST_SetSRID(ST_MakePoint(88.6556, 27.0875), 4326), 'downpour', 'landslide', 1, 'In Lava, Kalimpong one student of Class 9 was killed, and all roads to and from Lava are shut down', 'NASA GLC bulk import'),
  ('glc-3805', '2011-07-19', 27.05374234, 88.42572376, ST_SetSRID(ST_MakePoint(88.42572376, 27.05374234), 4326), 'rain', 'landslide', 0, 'The ongoing monsoons have once again started to take its toll along NH-31A, with various places along the West Bengal-Sikkim highway being blocked because of landslides, police said.  After closing down the highway for over 12 hours at Rambi in the West Bengal side on June 17, the rains have once again disrupted traffic along the highway since Tuesday.  “The highway is blocked at a place around 200 meters from Teesta Bridge towards Siliguri. The spot which is near the Shiv Mandir at the infamous Likhey Bhir is informed to have lost a section of the road due to heavy rains,” Janmukti Chalak Mahasangh’s (JCM) president Milan Pradhan said.  The section of the road broke down at around mid-night on Tuesday after which traffic came to a standstill with vehicles on either side returning back to their destinations or taking alternative routes via Darjeeling, Kurseong or Mirik, police said.  Drivers are also taking the route via Kalimpong-Lava-Gurubathan and Damdim and entering Siliguri throug', 'NASA GLC bulk import'),
  ('glc-7138', '2015-07-07', 27.0816, 88.4397, ST_SetSRID(ST_MakePoint(88.4397, 27.0816), 4326), 'continuous_rain', 'landslide', 0, 'the road was cleared by 7 am the next day.', 'NASA GLC bulk import'),
  ('glc-3619', '2011-06-17', 27.4885, 88.4451, ST_SetSRID(ST_MakePoint(88.4451, 27.4885), 4326), 'rain', 'mudslide', 0, 'The rain also triggered mudslides at two places on National Highway 31A, Sikkim’s only road link, holding up nearly 500 vehicles for five hours.', 'NASA GLC bulk import'),
  ('glc-9619', '2016-10-15', 27.1695, 88.3664, ST_SetSRID(ST_MakePoint(88.3664, 27.1695), 4326), 'rain', 'landslide', 0, 'The road on way to Peiling in Sikkim remained cut off due to landslides at Namchi and Rangpo but the Lava-Lolegaon route in Darjeeling was still working, though only for cars and the small vehicles took long detour through the second route, the officials said.', 'NASA GLC bulk import'),
  ('glc-2345', '2010-08-27', 27.3392, 88.6188, ST_SetSRID(ST_MakePoint(88.6188, 27.3392), 4326), 'downpour', 'landslide', 0, 'Gangtok, August 28, 2010  Heavy rains triggering landslides has affected large parts of Sikkim in which one person was killed and many houses were damaged, officials said today.   In the State capital Gangtok, a massive landslide in the residential area below Daragaon damaged four buildings last evening, forcing evacuations from these structures.', 'NASA GLC bulk import'),
  ('glc-1929', '2010-05-31', 27.3543, 88.6428, ST_SetSRID(ST_MakePoint(88.6428, 27.3543), 4326), 'downpour', 'landslide', 0, 'Over 500 tourists were stranded in the periphery of Gangtok since Monday night following multiple landslides triggered by heavy rainfall in Sikkim.  Sikkim Deputy Inspector General of Police S. Rao said the landslides occurred in the Sikkim East district around this capital town and famous tourist resort.  ''Over 500 stranded tourists had to spend the night under open skies. More than 100 vehicles were also stranded as the North Sikkim Highway was blocked,'' Rao said.  The Border Roads Organisation (BRO) personnel began clearing the highway and other roads in the morning and rescued the trapped tourists, who were then brought here.  The vehicles were then removed to Gangtok, Rao said.  The East Sikkim district has experienced 100 mm rain since Sunday.', 'NASA GLC bulk import'),
  ('glc-274', '2007-09-20', 27.0875, 88.4572, ST_SetSRID(ST_MakePoint(88.4572, 27.0875), 4326), 'rain', 'landslide', 0, 'Roads were in deplorable condition after multiple days of heavy rain caused landslides in area', 'NASA GLC bulk import'),
  ('glc-2341', '2010-08-26', 27.2319, 88.497, ST_SetSRID(ST_MakePoint(88.497, 27.2319), 4326), 'downpour', 'landslide', 0, 'Gangtok, Aug. 27: Seven landslides struck a 15km stretch of NH31A and crippled traffic on Sikkim’s only road link with the rest of the country after heavy rain lashed the Himalayan state last night. A 31-year-old woman was washed away in one of the flash floods that followed.  The landslides, four of them major ones, occurred between 32 Mile and Singtam on NH31A, the stretch littered with slush and debris that came tumbling down from the hillside late last night and early this morning.  The landslides left at least 100 vehicles coming from Siliguri stranded on the Bengal-Sikkim border at Rangpo for sometime. While some passengers tried to walk and cross the slides, others returned to Siliguri. “The vehicles — there were lots of them — were told to stay put at Singtam for the night,” said A.K. Singh, the executive engineer of Project Swastik of the Border Roads Organisation that is in charge of the highway. The first major landslide nearest to Gangtok was at the mouth of Topakhani, a 12', 'NASA GLC bulk import'),
  ('glc-269', '2007-09-18', 27.2872, 88.2816, ST_SetSRID(ST_MakePoint(88.2816, 27.2872), 4326), 'rain', 'landslide', 0, 'along multiple roads in province', 'NASA GLC bulk import'),
  ('glc-6964', '2015-06-17', 27.0087, 88.443, ST_SetSRID(ST_MakePoint(88.443, 27.0087), 4326), 'downpour', 'landslide', 0, 'Note: one article listed multiple landslides, unspecific. Following heavy rainfall in the Darjeeling hills, there were three landslides at three spots on National Highway 31A, considered the lifeline of Sikkim.', 'NASA GLC bulk import'),
  ('glc-7039', '2015-07-01', 27.0678, 88.456, ST_SetSRID(ST_MakePoint(88.456, 27.0678), 4326), 'downpour', 'landslide', 0, '15 people missing at 8th and 11th mile', 'NASA GLC bulk import'),
  ('glc-231', '2007-09-05', 27.06826195, 88.28121204, ST_SetSRID(ST_MakePoint(88.28121204, 27.06826195), 4326), 'rain', 'landslide', 15, 'damaged structures in area, one debris flow hit a jeep at 7:30am', 'NASA GLC bulk import'),
  ('glc-251', '2007-09-09', 27.1667, 88.35, ST_SetSRID(ST_MakePoint(88.35, 27.1667), 4326), 'rain', 'landslide', 1, 'many people displaced, houses damaged', 'NASA GLC bulk import'),
  ('glc-3944', '2011-08-25', 27.7344, 88.633, ST_SetSRID(ST_MakePoint(88.633, 27.7344), 4326), 'downpour', 'landslide', 2, 'Five persons including two minors were killed in two separate landslides incident in West Sikkim district, official sources said today. A cloud burst triggered a massive landslide at Samathang village, near Malbasey in West Sikkim in which three members of a family including two children were killed midnight last night, the sources said. Nirmaya Chettri (36) and her two daughters - Manju (16) and Anju (6) were killed while her husband Pratab Chettri was injured when the landslide destroyed their house, they said. In the second landslide incident two persons - Santa Bir Majhi and Sarki Maji working as casual labourers at a private construction site at Hee-Khola in West district were killed on the spot when loose muck from the construction site buried them in the site today, the sources said.', 'NASA GLC bulk import'),
  ('glc-4411', '2012-06-14', 27.339, 88.6065, ST_SetSRID(ST_MakePoint(88.6065, 27.339), 4326), 'downpour', 'landslide', 0, 'The continuous rainfall triggered a landslide on Thursday  morning at 4 am near Kamala Gas agency at Tathangchen, Gangtok.  Though no casualties were reported but the landslide has posed threat to some of the residence. Immediately after the occurrence the ward councilor, Mayor KN Topgay, Deputy Mayor Shakti Singh Chowdhury reached the spot.', 'NASA GLC bulk import'),
  ('glc-7033', '2015-06-29', 27.0161, 88.2478, ST_SetSRID(ST_MakePoint(88.2478, 27.0161), 4326), 'downpour', 'landslide', 0, 'We had to stop the service because debris have blocked the track at Merry Villa - S Sekhar. At present, all vehicles are waiting in a single file to enter and leave Darjeeling town. "Boulders are still blocking most of the road space." - Santosh Tamang', 'NASA GLC bulk import'),
  ('glc-6967', '2015-06-13', 27.0165, 88.2476, ST_SetSRID(ST_MakePoint(88.2476, 27.0165), 4326), 'downpour', 'landslide', 0, 'Massive landslide in West Bengal hit toy train service...Boulders and debris fell on the rail tracks caused by incessant rain followed by the landslide.', 'NASA GLC bulk import'),
  ('glc-5485', '2013-09-08', 27.6047, 88.6463, ST_SetSRID(ST_MakePoint(88.6463, 27.6047), 4326), 'rain', 'rock_fall', 1, '"On Monday, workers of Southern Engineering Works (SEW) Ltd, Chungthang (North Sikkim) were brought to Army Field Hospital with multiple injuries sustained after a landslide struck they were working in a light mechanical workshop near the project site. Heavy boulders fell over the shed, killing one of the workers instantly," Singha added. Among those brought in, Tersus Lakra (27) was suffering from hemorrhagic shock as a result of a traumatic amputation of right leg, a fractured left forearm, closed head injury and blunt trauma in the chest region. Another worker Gayan Singh (38) sustained fractures in his entire left leg. Several other workers sustained multiple laceration and abrasions. A surgical team and medical officers of the Army Field Hospital managed the casualties by timely resuscitation and surgery. The serious patients were transferred to a Gangtok hospital after hemodynamic stabilization.', 'NASA GLC bulk import'),
  ('glc-9604', '2016-10-12', 27.2676, 88.2891, ST_SetSRID(ST_MakePoint(88.2891, 27.2676), 4326), 'continuous_rain', 'landslide', 0, 'Another landslip occurred at Legship, near the tourist spot of Pelling, in Sikkim severely affecting road traffic movement between Darjeeling and Legship, officials said.', 'NASA GLC bulk import'),
  ('glc-620', '2008-06-30', 27.0771, 88.482, ST_SetSRID(ST_MakePoint(88.482, 27.0771), 4326), 'downpour', 'landslide', 0, 'Monsoon rains triggered heavy landslides in Kalimpong in Himalayas on Monday, snapping road link to Sikkim with rest of India.', 'NASA GLC bulk import'),
  ('glc-1030', '2009-05-26', 27.04357147, 88.26522126, ST_SetSRID(ST_MakePoint(88.26522126, 27.04357147), 4326), 'tropical_cyclone', 'landslide', 14, 'With the recovery of three more bodies, the toll in the landslides in West Bengal''s hill district of Darjeeling due to Cyclone Aila has risen to 27, police said today.   "We have recovered three bodies from the debris at Rangiabong under Jorbungalow police station area this (Thursday) morning. One of the bodies has been identified as Pramila Rai, 68," a senior official of the Jorbungalow police station said.   He said the teams of Natural Disaster Management Authority have started rescue operations in the cyclone-hit areas.   Meanwhile, state Home Secretary Ardhendu Sen reached Darjeeling Thursday morning to hold meetings with the district administration. He is likely to visit the landslide-affected zones and will also survey the situation there.   "Search operations are on in some areas as at least four people are still missing from the Darjeeling district after the cyclonic storm," the police officer said.   According to district administration sources, 14 bodies were found in ar', 'NASA GLC bulk import'),
  ('glc-11183', '2017-07-10', 27.360364, 88.651914, ST_SetSRID(ST_MakePoint(88.651914, 27.360364), 4326), 'unknown', 'rock_fall', 0, 'Many vehicles plying along the Rongey/Chongey road were crushed by a major landslide at Maney Khola Rongay, East Sikkim. According to reports posted by the Sikkim Police in facebook on Wednesday, Rongey/Chongey road was blocked at Maney Khola due to rock slide moment ago.', 'NASA GLC bulk import')
